async function generateSceneImage(illustrationPrompt, sceneId) {
  try {
    const fs2 = await import("fs");
    const path3 = await import("path");
    const filePath = path3.resolve(process.cwd(), "assets", "kids-scenes", `${sceneId}.png`);
    if (fs2.existsSync(filePath)) {
      return `/assets/kids-scenes/${sceneId}.png`;
    }
    return null;
  } catch (err) {
    console.error("Scene image lookup error:", err);
    return null;
  }
}
