init_api_client();
var ELEVENLABS_VOICES = {
  george: "JBFqnCBsd6RMkjVDRZzb",
  sarah: "EXAVITQu4vr4xnSDxMaL"
};
function isValidVoice(voice) {
  return Object.keys(ELEVENLABS_VOICES).includes(voice);
}
async function textToSpeech(text2, voice = "george", format = "mp3") {
  const voiceId = ELEVENLABS_VOICES[voice] || ELEVENLABS_VOICES.george;
  const apiKey = process.env.ELEVENLABS_API_KEY;
  if (!apiKey) {
    throw new Error("ELEVENLABS_API_KEY environment variable is not set.");
  }
  console.log(`[ElevenLabs TTS] Generating audio for voice="${voice}" (${voiceId}), text=${text2.length} chars`);
  const response = await fetchWithTimeout(`https://api.elevenlabs.io/v1/text-to-speech/${voiceId}?output_format=mp3_44100_128`, {
    service: "elevenlabs",
    serviceLabel: "elevenlabs-tts",
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "xi-api-key": apiKey
    },
    body: JSON.stringify({
      text: text2,
      model_id: "eleven_turbo_v2_5",
      voice_settings: {
        stability: 0.5,
        similarity_boost: 0.75
      }
    })
  });
  if (!response.ok) {
    const errText = await response.text();
    throw new Error(`ElevenLabs API error: ${response.status} ${errText}`);
  }
  const arrayBuffer = await response.arrayBuffer();
  const buf = Buffer.from(arrayBuffer);
  console.log(`[ElevenLabs TTS] Success: voice="${voice}", ${buf.length} bytes`);
  return buf;
}

