var roomService = new RoomServiceClient(httpUrl, LIVEKIT_API_KEY, LIVEKIT_API_SECRET);
function getLiveKitUrl() {
  return LIVEKIT_URL;
}
async function createLiveKitRoom(roomName) {
  try {
    await roomService.createRoom({
      name: roomName,
      emptyTimeout: 60 * 30,
      maxParticipants: 50
    });
  } catch (err) {
    if (err?.message?.includes("already exists")) return;
    throw err;
  }
}
async function deleteLiveKitRoom(roomName) {
  try {
    await roomService.deleteRoom(roomName);
  } catch (err) {
    console.error("Failed to delete LiveKit room:", err);
  }
}
async function generateToken(roomName, participantName, isHost = false) {
  const identity = `${participantName.replace(/[^a-zA-Z0-9_-]/g, "_")}_${Date.now().toString(36)}`;
  const token = new AccessToken(LIVEKIT_API_KEY, LIVEKIT_API_SECRET, {
    identity,
    name: participantName,
    ttl: "6h"
  });
  token.addGrant({
    room: roomName,
    roomJoin: true,
    canPublish: true,
    canSubscribe: true,
    canPublishData: true,
    roomAdmin: isHost
  });
  return await token.toJwt();
}

