function resolveContentLang(req) {
  const raw = String(req.query.lang || "").trim().toLowerCase();
  if (!raw || raw === "en") return null;
  const base = raw.split("-")[0];
  if (CONTENT_LANGUAGES.includes(base)) return base;
  return null;
}

